const isTouchFirstDevice = () =>
  typeof window !== "undefined" &&
  (window.innerWidth <= 1024 ||
    window.matchMedia?.("(pointer: coarse)").matches ||
    navigator.maxTouchPoints > 0 ||
    "ontouchstart" in window);

const shouldAutoFocusTextInput = () => !isTouchFirstDevice();

const blurFocusedTextInput = () => {
  if (typeof document === "undefined") return;
  const activeElement = document.activeElement;
  if (
    activeElement instanceof HTMLElement &&
    activeElement.matches("input, textarea, [contenteditable='true']")
  ) {
    activeElement.blur();
  }
};

let _touchStartY = 0;
let _touchStartX = 0;
let _isTouchScrolling = false;

if (typeof window !== "undefined") {
  window.addEventListener(
    "touchstart",
    (e) => {
      _touchStartY = e.touches[0].clientY;
      _touchStartX = e.touches[0].clientX;
      _isTouchScrolling = false;
    },
    { passive: true },
  );
  window.addEventListener(
    "touchmove",
    (e) => {
      if (_isTouchScrolling) return;
      const dy = Math.abs(e.touches[0].clientY - _touchStartY);
      const dx = Math.abs(e.touches[0].clientX - _touchStartX);
      if (dy > 10 || dx > 10) _isTouchScrolling = true;
    },
    { passive: true },
  );
}

const selectFromTouch = (event: any, select: () => void) => {
  if (_isTouchScrolling) return;
  event.preventDefault();
  event.stopPropagation();
  blurFocusedTextInput();
  select();
};

function useDismissiblePopover(
  open: boolean,
  setOpen: (next: boolean) => void,
) {
  const rootRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const closeOutside = (event: Event) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false);
    };
    const closeWithEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };
    document.addEventListener("pointerdown", closeOutside, true);
    document.addEventListener("touchstart", closeOutside, {
      capture: true,
      passive: true,
    });
    document.addEventListener("keydown", closeWithEscape);
    return () => {
      document.removeEventListener("pointerdown", closeOutside, true);
      document.removeEventListener("touchstart", closeOutside, true);
      document.removeEventListener("keydown", closeWithEscape);
    };
  }, [open, setOpen]);
  return rootRef;
}

const normalizeNumberInput = (input: HTMLInputElement) => {
  input.value = normalizeDecimalDraft(input.value);
  return input.value;
};

function DecimalInput({
  value,
  onValue,
  label,
}: {
  value: number;
  onValue: (value: number) => void;
  label?: string;
}) {
  const [draft, setDraft] = useState(
    String(Number.isFinite(value) ? value : 0),
  );
  useEffect(() => {
    if (nonNegativeNumber(draft) !== nonNegativeNumber(value))
      setDraft(String(nonNegativeNumber(value)));
  }, [value, draft]);
  return (
    <input
      aria-label={label}
      type="text"
      inputMode="decimal"
      value={draft}
      onInput={(event) => {
        const next = event.currentTarget.value;
        if (!isDecimalDraft(next)) return;
        const normalized = normalizeDecimalDraft(next);
        setDraft(normalized);
        onValue(nonNegativeNumber(normalized));
      }}
      onBlur={() => {
        const normalized = nonNegativeNumber(draft);
        setDraft(String(normalized));
        onValue(normalized);
      }}
    />
  );
}

const formatRupiahInput = (value: number) =>
  Math.round(nonNegativeNumber(value)).toLocaleString("id-ID");

function RupiahInput({
  value,
  onValue,
  label,
  readOnly = false,
}: {
  value: number;
  onValue: (value: number) => void;
  label?: string;
  readOnly?: boolean;
}) {
  const normalizedValue = Math.round(nonNegativeNumber(value));
  const [draft, setDraft] = useState(String(normalizedValue));
  const [focused, setFocused] = useState(false);
  useEffect(() => {
    if (!focused && Number(draft || 0) !== normalizedValue)
      setDraft(String(normalizedValue));
  }, [normalizedValue, focused, draft]);
  return (
    <input
      aria-label={label}
      type="text"
      inputMode="numeric"
      readOnly={readOnly}
      value={
        focused && !readOnly
          ? draft === ""
            ? ""
            : formatRupiahInput(Number(draft))
          : formatRupiahInput(normalizedValue)
      }
      onFocus={(event) => {
        if (readOnly) return;
        const input = event.currentTarget;
        setDraft(String(normalizedValue));
        setFocused(true);
        requestAnimationFrame(() => {
          if (input.isConnected) input.select();
        });
      }}
      onChange={(event) => {
        const digits = event.currentTarget.value
          .replace(/\D/g, "")
          .replace(/^0+(?=\d)/, "");
        const next = digits === "" ? "" : digits;
        setDraft(next);
        onValue(Number(next || 0));
      }}
      onBlur={() => {
        const next = Math.round(nonNegativeNumber(draft));
        setDraft(String(next));
        setFocused(false);
        onValue(next);
      }}
    />
  );
}

function OptionalRupiahInput({
  value,
  onValue,
  label,
  inputRef,
}: {
  value: string;
  onValue: (value: string) => void;
  label?: string;
  inputRef?: React.Ref<HTMLInputElement>;
}) {
  return (
    <input
      ref={inputRef}
      aria-label={label}
      type="text"
      inputMode="numeric"
      value={value === "" ? "" : formatRupiahInput(Number(value))}
      placeholder="Opsional"
      onFocus={(event) => {
        const input = event.currentTarget;
        requestAnimationFrame(() => {
          if (input.isConnected) input.select();
        });
      }}
      onInput={(event) =>
        onValue(
          event.currentTarget.value.replace(/\D/g, "").replace(/^0+(?=\d)/, ""),
        )
      }
    />
  );
}

