interface BulkMappedLine {
  variantId: string;
  quantity: number;
  grossAmount: number;
  netSalesAmount: number;
  externalSkus: string[];
}

function BulkOnlineProcessor({
  data,
  variants,
  loc,
  save,
  notify,
  checkMarketplaceImport,
}: any) {
  const [loading, setLoading] = useState<"orders" | "income" | "save" | null>(null);
  const [orders, setOrders] = useState<TikTokOrderParseResult | null>(null);
  const [income, setIncome] = useState<TikTokIncomeParseResult | null>(null);
  const [manualMappings, setManualMappings] = useState<Record<string, string>>({});
  const [manualPlatformFee, setManualPlatformFee] = useState(0);
  const [duplicateOrderIds, setDuplicateOrderIds] = useState<Set<string>>(
    () => new Set(),
  );
  const [duplicateFingerprint, setDuplicateFingerprint] = useState(false);
  const [mappingSearch, setMappingSearch] = useState("");
  const [mappingPage, setMappingPage] = useState(0);

  const newRows = useMemo(
    () =>
      (orders?.eligibleRows || []).filter(
        (row) => !duplicateOrderIds.has(row.orderId),
      ),
    [duplicateOrderIds, orders],
  );
  const externalGroups = useMemo(() => {
    const groups = new Map<
      string,
      {
        externalSku: string;
        productName: string;
        variation: string;
        rows: ParsedTikTokOrder[];
        quantity: number;
        grossAmount: number;
        netSalesAmount: number;
      }
    >();
    for (const row of newRows) {
      const current = groups.get(row.externalSku) || {
        externalSku: row.externalSku,
        productName: row.productName,
        variation: row.variation,
        rows: [],
        quantity: 0,
        grossAmount: 0,
        netSalesAmount: 0,
      };
      current.rows.push(row);
      current.quantity += row.netQuantity;
      current.grossAmount += row.grossAmount;
      current.netSalesAmount += row.netSalesAmount;
      groups.set(row.externalSku, current);
    }
    return Array.from(groups.values());
  }, [newRows]);
  const persistedMappings = useMemo(
    () =>
      new Map<string, string>(
        (data.marketplaceSkuMappings || [])
          .filter((mapping: any) => mapping.platform === "tiktok")
          .map(
            (mapping: any) =>
              [String(mapping.externalSku), String(mapping.variantId)] as [
                string,
                string,
              ],
          ),
      ),
    [data.marketplaceSkuMappings],
  );
  const exactSkuMappings = useMemo(
    () =>
      new Map<string, string>(
        variants
          .filter((variant: any) => String(variant.sku || "").trim())
          .map(
            (variant: any) =>
              [
                String(variant.sku).trim().toLowerCase(),
                String(variant.id),
              ] as [string, string],
          ),
      ),
    [variants],
  );
  const resolvedGroups = useMemo(
    () =>
      externalGroups.map((group) => ({
        ...group,
        variantId:
          manualMappings[group.externalSku] ||
          persistedMappings.get(group.externalSku) ||
          exactSkuMappings.get(group.externalSku.trim().toLowerCase()) ||
          "",
      })),
    [externalGroups, exactSkuMappings, manualMappings, persistedMappings],
  );
  const unmatched = resolvedGroups.filter(
    (group) =>
      !group.variantId ||
      !variants.some((variant: any) => variant.id === group.variantId),
  );
  const filteredUnmatched = useMemo(() => {
    const query = mappingSearch.trim().toLowerCase();
    if (!query) return unmatched;
    return unmatched.filter((group) =>
      `${group.productName} ${group.variation} ${group.externalSku}`
        .toLowerCase()
        .includes(query),
    );
  }, [mappingSearch, unmatched]);
  const mappingPageSize = 30;
  const mappingPageCount = Math.max(
    1,
    Math.ceil(filteredUnmatched.length / mappingPageSize),
  );
  const visibleUnmatched = filteredUnmatched.slice(
    mappingPage * mappingPageSize,
    (mappingPage + 1) * mappingPageSize,
  );
  useEffect(() => {
    setMappingPage((current) => Math.min(current, mappingPageCount - 1));
  }, [mappingPageCount]);
  const mappedLines = useMemo(() => {
    const lines = new Map<string, BulkMappedLine>();
    for (const group of resolvedGroups) {
      if (!group.variantId) continue;
      const current: BulkMappedLine = lines.get(group.variantId) || {
        variantId: group.variantId,
        quantity: 0,
        grossAmount: 0,
        netSalesAmount: 0,
        externalSkus: [],
      };
      current.quantity += group.quantity;
      current.grossAmount += group.grossAmount;
      current.netSalesAmount += group.netSalesAmount;
      current.externalSkus.push(group.externalSku);
      lines.set(group.variantId, current);
    }
    return Array.from(lines.values());
  }, [resolvedGroups]);
  const stockErrors = mappedLines.filter(
    (line) => line.quantity > getBalance(data.balances, loc, line.variantId),
  );
  const importedOrderIds = useMemo(
    () => Array.from(new Set(newRows.map((row) => row.orderId))),
    [newRows],
  );
  const incomeTotals = useMemo(() => {
    if (!income) return null;
    return importedOrderIds.reduce(
      (totals, orderId) => {
        const row = income.orders[orderId];
        if (row) {
          totals.matchedOrders += 1;
          totals.platformFee += row.platformFee;
          totals.netPayout += row.netPayout;
        }
        return totals;
      },
      { matchedOrders: 0, platformFee: 0, netPayout: 0 },
    );
  }, [importedOrderIds, income]);
  const grossTotal = mappedLines.reduce((sum, line) => sum + line.grossAmount, 0);
  const netSalesTotal = mappedLines.reduce(
    (sum, line) => sum + line.netSalesAmount,
    0,
  );
  const platformFee = incomeTotals?.platformFee ?? manualPlatformFee;
  const netPayout = incomeTotals
    ? incomeTotals.netPayout
    : Math.max(0, netSalesTotal - platformFee);
  const canSave = Boolean(
    orders &&
      importedOrderIds.length &&
      mappedLines.length &&
      !unmatched.length &&
      !stockErrors.length &&
      !duplicateFingerprint &&
      loading === null,
  );

  const uploadOrders = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    setLoading("orders");
    try {
      const parsed = await parseTikTokOrders(file);
      const check = await checkMarketplaceImport({
        locationId: loc,
        platform: "tiktok",
        fingerprint: parsed.fingerprint,
        externalOrderIds: Array.from(
          new Set(parsed.eligibleRows.map((row) => row.orderId)),
        ),
      });
      setOrders(parsed);
      setDuplicateFingerprint(check.fileImported);
      setDuplicateOrderIds(new Set(check.duplicateOrderIds));
      setIncome(null);
      setManualMappings({});
      setManualPlatformFee(0);
      setMappingSearch("");
      setMappingPage(0);
    } catch (error) {
      setOrders(null);
      setDuplicateFingerprint(false);
      setDuplicateOrderIds(new Set());
      notify(
        error instanceof Error ? error.message : "File pesanan gagal dibaca.",
        "error",
      );
    } finally {
      setLoading(null);
    }
  };

  const uploadIncome = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    setLoading("income");
    try {
      setIncome(await parseTikTokIncome(file));
    } catch (error) {
      setIncome(null);
      notify(
        error instanceof Error
          ? error.message
          : "File pendapatan TikTok gagal dibaca.",
        "error",
      );
    } finally {
      setLoading(null);
    }
  };

  const submitImport = async () => {
    if (!canSave || !orders) return;
    setLoading("save");
    try {
      await save(
        loc,
        "online",
        mappedLines.map((line) => ({
          variantId: line.variantId,
          quantity: line.quantity,
          grossAmount: line.grossAmount,
          netSalesAmount: line.netSalesAmount,
        })),
        "Transfer",
        false,
        0,
        "nominal",
        0,
        `Impor TikTok · ${importedOrderIds.length} pesanan`,
        platformFee,
        {
          netPayout,
          sourceImport: {
            platform: "tiktok",
            fingerprint: orders.fingerprint,
            incomeFingerprint: income?.fingerprint,
            sourceFileName: orders.sourceFileName,
            incomeFileName: income?.sourceFileName,
            externalOrderIds: importedOrderIds,
            rowCount: newRows.length,
            ignoredRowCount: orders.ignoredRows.length,
            duplicateOrderCount: duplicateOrderIds.size,
          },
          skuMappings: resolvedGroups.map((group) => ({
            externalSku: group.externalSku,
            variantId: group.variantId,
          })),
        },
      );
      setOrders(null);
      setIncome(null);
      setManualMappings({});
      setManualPlatformFee(0);
      setDuplicateFingerprint(false);
      setDuplicateOrderIds(new Set());
      setMappingSearch("");
      setMappingPage(0);
    } catch (error) {
      notify(
        error instanceof Error ? error.message : "Impor TikTok gagal disimpan.",
        "error",
      );
    } finally {
      setLoading(null);
    }
  };

  return (
    <section className="bulk-online-import">
      <header className="bulk-online-heading">
        <div>
          <small>IMPOR MARKETPLACE</small>
          <h3>Rekap penjualan TikTok</h3>
          <p>
            Pesanan belum dibayar, dibatalkan, sudah diretur penuh, dan yang
            pernah diimpor tidak akan memotong stok.
          </p>
        </div>
      </header>

      <div className="bulk-online-upload-grid">
        <label className="bulk-file-card">
          <Upload size={20} />
          <span>
            <b>1. Laporan pesanan</b>
            <small>{orders?.sourceFileName || "Semua pesanan-....xlsx · wajib"}</small>
          </span>
          <input type="file" accept=".xlsx" onChange={uploadOrders} disabled={loading !== null} />
        </label>
        <label className={`bulk-file-card ${!orders ? "disabled" : ""}`}>
          <Upload size={20} />
          <span>
            <b>2. Laporan pendapatan</b>
            <small>{income?.sourceFileName || "income_....xlsx · opsional"}</small>
          </span>
          <input
            type="file"
            accept=".xlsx"
            onChange={uploadIncome}
            disabled={!orders || loading !== null}
          />
        </label>
      </div>
      {loading === "orders" && <p className="bulk-progress">Membaca dan memvalidasi laporan pesanan…</p>}
      {loading === "income" && <p className="bulk-progress">Merekonsiliasi biaya marketplace…</p>}

      {orders && (
        <>
          <div className="bulk-preview-metrics">
            <span><b>{importedOrderIds.length.toLocaleString("id-ID")}</b> pesanan baru</span>
            <span><b>{newRows.length.toLocaleString("id-ID")}</b> baris layak</span>
            <span><b>{orders.ignoredRows.length.toLocaleString("id-ID")}</b> baris diabaikan</span>
            <span><b>{duplicateOrderIds.size.toLocaleString("id-ID")}</b> pesanan duplikat</span>
          </div>

          {duplicateFingerprint && (
            <div className="bulk-alert danger">
              <AlertTriangle size={18} /> File pesanan ini sudah pernah diimpor.
            </div>
          )}
          {!newRows.length && !duplicateFingerprint && (
            <div className="bulk-alert warning">
              <Info size={18} /> Tidak ada pesanan baru yang dapat diimpor dari file ini.
            </div>
          )}
          {unmatched.length > 0 && (
            <div className="bulk-mapping-panel">
              <div className="bulk-panel-title">
                <span>
                  <AlertTriangle size={18} />
                  <b>{unmatched.length} SKU perlu dipasangkan</b>
                </span>
                <small>Pilih varian yang tepat. Pilihan akan disimpan untuk impor berikutnya.</small>
              </div>
              <div className="bulk-mapping-tools">
                <input
                  type="search"
                  value={mappingSearch}
                  onChange={(event) => {
                    setMappingSearch(event.target.value);
                    setMappingPage(0);
                  }}
                  placeholder="Cari produk, variasi, atau SKU TikTok"
                  aria-label="Cari SKU TikTok yang perlu dipasangkan"
                />
                <small>
                  {filteredUnmatched.length.toLocaleString("id-ID")} dari{" "}
                  {unmatched.length.toLocaleString("id-ID")} SKU
                </small>
              </div>
              <div className="bulk-mapping-list">
                {visibleUnmatched.map((group) => (
                  <label key={group.externalSku} className="bulk-mapping-row">
                    <span>
                      <b>{group.productName || "Produk TikTok"}</b>
                      <small>{group.variation || group.externalSku} · Qty {group.quantity}</small>
                    </span>
                    <select
                      value={manualMappings[group.externalSku] || ""}
                      onChange={(event) =>
                        setManualMappings((current) => ({
                          ...current,
                          [group.externalSku]: event.target.value,
                        }))
                      }
                    >
                      <option value="">Pilih varian Menengs</option>
                      {variants.map((variant: any) => (
                        <option key={variant.id} value={variant.id}>
                          {variant.productName} · {variant.name} · stok {getBalance(data.balances, loc, variant.id)}
                        </option>
                      ))}
                    </select>
                  </label>
                ))}
              </div>
              {filteredUnmatched.length > mappingPageSize && (
                <div className="bulk-mapping-pagination">
                  <button
                    type="button"
                    className="secondary"
                    disabled={mappingPage === 0}
                    onClick={() => setMappingPage((page) => Math.max(0, page - 1))}
                  >
                    Sebelumnya
                  </button>
                  <span>
                    Halaman {mappingPage + 1} dari {mappingPageCount}
                  </span>
                  <button
                    type="button"
                    className="secondary"
                    disabled={mappingPage >= mappingPageCount - 1}
                    onClick={() =>
                      setMappingPage((page) =>
                        Math.min(mappingPageCount - 1, page + 1),
                      )
                    }
                  >
                    Berikutnya
                  </button>
                </div>
              )}
            </div>
          )}

          {mappedLines.length > 0 && (
            <div className="bulk-matched-panel">
              <div className="bulk-panel-title">
                <b>{mappedLines.length} varian siap dicatat</b>
                <small>Hanya varian pada preview ini yang akan mengurangi stok.</small>
              </div>
              <div className="bulk-matched-list">
                {mappedLines.map((line) => {
                  const variant = variants.find((item: any) => item.id === line.variantId);
                  const available = getBalance(data.balances, loc, line.variantId);
                  return (
                    <div key={line.variantId} className="bulk-matched-row">
                      <span>
                        <b>{variant?.productName} · {variant?.name}</b>
                        <small>Stok {available} · dipotong {line.quantity}</small>
                      </span>
                      <strong>{money(line.netSalesAmount)}</strong>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
          {stockErrors.length > 0 && (
            <div className="bulk-alert danger">
              <AlertTriangle size={18} /> Stok {stockErrors.length} varian tidak mencukupi. Perbarui stok atau koreksi pemetaan.
            </div>
          )}

          <div className="bulk-finance-panel">
            <div className="bulk-finance-summary">
              <span><small>Omzet sebelum diskon penjual</small><b>{money(grossTotal)}</b></span>
              <span><small>Omzet penjualan</small><b>{money(netSalesTotal)}</b></span>
              <span><small>Biaya marketplace</small><b>{money(platformFee)}</b></span>
              <span><small>Pencairan tercatat</small><b>{money(netPayout)}</b></span>
            </div>
            {incomeTotals ? (
              <p className="bulk-reconcile-note">
                Biaya otomatis cocok untuk {incomeTotals.matchedOrders} dari {importedOrderIds.length} pesanan. Pesanan yang belum cair tetap tercatat dengan biaya Rp 0.
              </p>
            ) : (
              <div className="bulk-manual-fee">
                <RupiahInput
                  label="Biaya marketplace (opsional)"
                  value={manualPlatformFee}
                  onValue={setManualPlatformFee}
                />
                <small>Unggah laporan pendapatan agar biaya dan pencairan terisi otomatis.</small>
              </div>
            )}
          </div>

          <button
            type="button"
            className="primary bulk-save-button"
            onClick={submitImport}
            disabled={!canSave}
          >
            <Check size={18} />
            {loading === "save"
              ? "Menyimpan impor…"
              : `Simpan ${importedOrderIds.length.toLocaleString("id-ID")} Pesanan`}
          </button>
        </>
      )}
    </section>
  );
}

function SaleModal({
  data,
  close,
  save,
  finalizePrint,
  abortPrint,
  fixedLocation,
  defaultLocation,
  notify,
  checkMarketplaceImport,
  initialChannel = "offline",
}: any) {
  const activeLocations = data.locations.filter((l: any) => l.active),
    variants = data.products
      .filter((p: any) => p.active)
      .flatMap((p: any) =>
        p.variants
          .filter((item: any) => item.active !== false)
          .map((item: any) => ({
            ...item,
            unit: p.unit,
            productName: p.name,
            category: p.category,
            productImageUrl: p.imageUrl || p.image || item.imageUrl,
          })),
      ),
    [loc, setLoc] = useState(
      fixedLocation ||
        activeLocations.find((location: any) => location.id === defaultLocation)
          ?.id ||
        activeLocations[0]?.id ||
        "",
    ),
    [channel, setChannel] = useState<Channel>(initialChannel),
    [skuSearch, setSkuSearch] = useState(""),
    [categoryFilter, setCategoryFilter] = useState("all"),
    [selectedPosProduct, setSelectedPosProduct] = useState<string | null>(null),
    [posPackageFilter, setPosPackageFilter] = useState("all"),
    [posFlavorFilter, setPosFlavorFilter] = useState("all"),
    [posLevelFilter, setPosLevelFilter] = useState("all"),
    [payment, setPayment] = useState("QRIS"),
    [onlineInputMode, setOnlineInputMode] = useState<"satuan" | "bulk">("satuan"),
    [discountType, setDiscountType] = useState<"nominal" | "percentage">(
      "nominal",
    ),
    [discountValue, setDiscountValue] = useState(0),
    [buyerNote, setBuyerNote] = useState(""),
    [transactionSettingsOpen, setTransactionSettingsOpen] = useState(false),
    [cart, setCart] = useState<Array<{ variantId: string; quantity: number }>>(
      [],
    ),
    [printerSettings, setPrinterSettings] = useState<PrinterSettings>(() =>
      loadPrinterSettings(),
    ),
    [printReceipt, setPrintReceipt] = useState(false),
    [saving, setSaving] = useState(false),
    [pendingSale, setPendingSale] = useState<any>(null),
    [printError, setPrintError] = useState(""),
    [cameraOpen, setCameraOpen] = useState(false),
    [cameraError, setCameraError] = useState(""),
    categories = Array.from(
      new Set(variants.map((item: any) => item.category).filter(Boolean)),
    ).sort() as string[],
    selectedPosProductVariants = selectedPosProduct
      ? variants.filter(
          (item: any) =>
            item.productName === selectedPosProduct &&
            (getBalance(data.balances, loc, item.id) > 0 ||
              cart.some((cartItem) => cartItem.variantId === item.id)),
        )
      : [],
    posVariantFilterOptions = (field: string) =>
      Array.from(
        new Set(
          selectedPosProductVariants
            .map((item: any) => String(item[field] || "").trim())
            .filter(Boolean),
        ),
      ).sort((a: any, b: any) =>
        String(a).localeCompare(String(b), "id", {
          numeric: true,
          sensitivity: "base",
        }),
      ),
    posPackageOptions = posVariantFilterOptions("packageWeight"),
    posFlavorOptions = posVariantFilterOptions("flavor"),
    posLevelOptions = posVariantFilterOptions("spiceLevel"),
    matchingVariants = variants.filter(
      (item: any) =>
        (categoryFilter === "all" || item.category === categoryFilter) &&
        (!selectedPosProduct ||
          (posPackageFilter === "all" ||
            item.packageWeight === posPackageFilter) &&
            (posFlavorFilter === "all" || item.flavor === posFlavorFilter) &&
            (posLevelFilter === "all" ||
              item.spiceLevel === posLevelFilter)) &&
        `${item.sku || ""} ${item.barcode || ""} ${item.productName} ${item.name} ${item.packageWeight || ""} ${item.flavor || ""} ${item.spiceLevel || ""}`
          .toLowerCase()
          .includes(skuSearch.toLowerCase()),
    ),
    sellableMatchingVariants = matchingVariants.filter(
      (item: any) =>
        getBalance(data.balances, loc, item.id) > 0 ||
        cart.some((c) => c.variantId === item.id),
    );
  const resetPosVariantFilters = () => {
    setPosPackageFilter("all");
    setPosFlavorFilter("all");
    setPosLevelFilter("all");
  };
  const prepareNextSale = () => {
    setCart([]);
    setDiscountType("nominal");
    setDiscountValue(0);
    setBuyerNote("");
    setSkuSearch("");
    setSelectedPosProduct(null);
    resetPosVariantFilters();
    setCameraError("");
    setPrintError("");
    setPendingSale(null);
    setSaving(false);
    if (shouldAutoFocusPosSearch)
      requestAnimationFrame(() => scannerRef.current?.focus());
  };
  const finishPendingSale = async () => {
    if (!pendingSale) return;
    await finalizePrint(pendingSale.sale.id);
    notify("Struk sudah tercetak. POS siap untuk transaksi berikutnya.");
    prepareNextSale();
  };
  const printPendingSale = async (result = pendingSale) => {
    if (!result) return;
    setPrintError("");
    if (printerSettings.mode === "system")
      systemPrintSale(result.sale, result.data, printerSettings);
    else await directPrintSale(result.sale, result.data, printerSettings);
    setPendingSale(result);
    setSaving(false);
    notify(
      "Data struk sudah dikirim. Konfirmasi hanya setelah kertas benar-benar keluar.",
    );
  };
  const cancelPendingSale = async () => {
    if (!pendingSale || saving) return;
    setSaving(true);
    try {
      await abortPrint(pendingSale.sale.id);
      notify(
        "Transaksi dibatalkan dan stok dikembalikan. POS siap digunakan kembali.",
      );
      prepareNextSale();
    } catch (error) {
      notify(
        error instanceof Error
          ? error.message
          : "Transaksi menunggu cetak tidak dapat dibatalkan.",
        "error",
      );
      setSaving(false);
    }
  };
  const visibleProductGroups = Object.values(
    sellableMatchingVariants.reduce(
      (groups: Record<string, any>, variant: any) => {
        if (!groups[variant.productName])
          groups[variant.productName] = {
            name: variant.productName,
            imageUrl: variant.productImageUrl,
            variants: [],
          };
        groups[variant.productName].variants.push(variant);
        return groups;
      },
      {},
    ),
  );
  const scannerRef = useRef<HTMLInputElement>(null);
  const scannerVideoRef = useRef<HTMLVideoElement>(null);
  const scannerStreamRef = useRef<MediaStream | null>(null);
  const barcodePhotoRef = useRef<HTMLInputElement>(null);
  const scanAudioContextRef = useRef<AudioContext | null>(null);
  const isOffline = channel === "offline";
  const isTouchDevice =
    typeof window !== "undefined" &&
    (window.matchMedia?.("(pointer: coarse)").matches ||
      navigator.maxTouchPoints > 0 ||
      "ontouchstart" in window);
  const shouldAutoFocusPosSearch =
    typeof window !== "undefined" &&
    !isTouchDevice &&
    window.innerWidth > 1024;
  const releasePosSearchFocus = () => {
    blurFocusedTextInput();
    requestAnimationFrame(() => scannerRef.current?.blur());
  };
  const findScannedVariant = (rawValue: string) => {
    const value = rawValue.trim().toLowerCase();
    if (!value) return undefined;
    return variants.find(
      (item: any) =>
        (item.sku?.toLowerCase() === value ||
          item.barcode?.toLowerCase() === value) &&
        getBalance(data.balances, loc, item.id) > 0,
    );
  };
  const addToCart = (variantId: string) => {
    setCart((current) => {
      const found = current.find((item) => item.variantId === variantId);
      const available = getBalance(data.balances, loc, variantId);
      if ((found?.quantity || 0) >= available) return current;
      return found
        ? current.map((item) =>
            item.variantId === variantId
              ? { ...item, quantity: item.quantity + 1 }
              : item,
          )
        : [...current, { variantId, quantity: 1 }];
    });
    setSkuSearch("");
  };
  const getScanAudioContext = () => {
    const AudioContextConstructor =
      window.AudioContext || (window as any).webkitAudioContext;
    if (!AudioContextConstructor) return null;
    if (
      !scanAudioContextRef.current ||
      scanAudioContextRef.current.state === "closed"
    ) {
      scanAudioContextRef.current = new AudioContextConstructor();
    }
    return scanAudioContextRef.current;
  };
  const primeScanAudio = () => {
    const context = getScanAudioContext();
    if (context?.state === "suspended")
      void context.resume().catch(() => undefined);
  };
  const playScanSuccessSound = () => {
    const context = getScanAudioContext();
    if (!context) return;
    const play = () => {
      const now = context.currentTime;
      const makeTone = (frequency: number, start: number, duration: number) => {
        const oscillator = context.createOscillator();
        const gain = context.createGain();
        oscillator.type = "square";
        oscillator.frequency.setValueAtTime(frequency, start);
        gain.gain.setValueAtTime(0.0001, start);
        gain.gain.exponentialRampToValueAtTime(0.045, start + 0.004);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
        oscillator.connect(gain).connect(context.destination);
        oscillator.start(start);
        oscillator.stop(start + duration + 0.01);
      };
      // Dua bunyi pendek memberi konfirmasi yang jelas seperti scanner kasir,
      // namun volumenya sengaja rendah agar tidak mengganggu area outlet.
      makeTone(1_450, now, 0.052);
      makeTone(2_050, now + 0.064, 0.072);
    };
    if (context.state === "suspended")
      void context
        .resume()
        .then(play)
        .catch(() => undefined);
    else play();
  };
  const applyScannedValue = (rawValue: string) => {
    const candidate =
      findScannedVariant(rawValue) ||
      (sellableMatchingVariants.length === 1
        ? sellableMatchingVariants[0]
        : undefined);
    if (!candidate) return false;
    addToCart(candidate.id);
    playScanSuccessSound();
    return true;
  };
  const stopCameraScanner = () => {
    scannerStreamRef.current?.getTracks().forEach((track) => track.stop());
    scannerStreamRef.current = null;
    if (scannerVideoRef.current) scannerVideoRef.current.srcObject = null;
    setCameraOpen(false);
  };
  const getCameraPermissionError = async (error: any) => {
    if (error?.name !== "NotAllowedError") return null;
    try {
      const permission = await navigator.permissions?.query({
        name: "camera" as PermissionName,
      });
      if (permission?.state === "denied") {
        return "Izin kamera untuk situs Menengs masih diblokir di Chrome. Ketuk ikon pengaturan di kiri alamat situs → Izin → Kamera → Izinkan, lalu muat ulang halaman.";
      }
    } catch {
      // Browser lama tidak selalu mendukung Permissions API untuk kamera.
    }
    return "Kamera ditolak oleh perangkat atau browser. Pastikan Chrome tidak sedang memakai kamera di aplikasi lain, lalu coba kembali.";
  };
  const openCameraScanner = async () => {
    setCameraError("");
    if (!navigator.mediaDevices?.getUserMedia) {
      setCameraError(
        "Kamera tidak tersedia di perangkat ini. Gunakan scanner Bluetooth atau masukkan SKU.",
      );
      return;
    }
    if (!(window as any).BarcodeDetector) {
      setCameraError(
        "Browser ini belum mendukung pembacaan barcode kamera. Gunakan Chrome terbaru atau scanner Bluetooth.",
      );
      return;
    }
    try {
      // getUserMedia wajib dipanggil langsung dari event klik. Di sebagian
      // Android, pemanggilan yang ditunda lewat effect dianggap bukan aksi
      // pengguna dan akan ditolak walaupun izin Chrome sudah aktif.
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: { ideal: "environment" },
          width: { ideal: 1280 },
          height: { ideal: 720 },
        },
        audio: false,
      });
      scannerStreamRef.current = stream;
      setCameraOpen(true);
    } catch (error: any) {
      const messageByErrorName: Record<string, string> = {
        NotFoundError: "Kamera tidak ditemukan pada perangkat ini.",
        NotReadableError:
          "Kamera sedang digunakan aplikasi lain. Tutup aplikasi Kamera, WhatsApp, atau Instagram lalu coba lagi.",
        OverconstrainedError:
          "Kamera belakang tidak dapat digunakan. Coba lagi setelah menutup aplikasi lain.",
      };
      setCameraError(
        (await getCameraPermissionError(error)) ||
          messageByErrorName[error?.name] ||
          "Kamera tidak dapat dibuka. Coba lagi atau gunakan scanner Bluetooth.",
      );
      stopCameraScanner();
    }
  };
  const scanBarcodePhoto = async (
    event: React.ChangeEvent<HTMLInputElement>,
  ) => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    setCameraError("");
    try {
      const Detector = (window as any).BarcodeDetector;
      if (!Detector) throw new Error("unsupported");
      const imageUrl = URL.createObjectURL(file);
      const image = new Image();
      await new Promise<void>((resolve, reject) => {
        image.onload = () => resolve();
        image.onerror = () => reject(new Error("invalid-image"));
        image.src = imageUrl;
      });
      const codes = await new Detector().detect(image);
      URL.revokeObjectURL(imageUrl);
      const rawValue = codes[0]?.rawValue;
      if (!rawValue) {
        setCameraError(
          "Barcode belum terbaca dari foto. Pastikan barcode terlihat utuh dan pencahayaan cukup.",
        );
      } else if (!applyScannedValue(rawValue)) {
        setCameraError(
          "Barcode ditemukan, tetapi produknya tidak tersedia pada stok lokasi ini.",
        );
      }
    } catch {
      setCameraError(
        "Foto barcode tidak dapat dipindai di browser ini. Gunakan input SKU atau scanner Bluetooth.",
      );
    }
  };
  const updateQuantity = (variantId: string, quantity: number) => {
    if (quantity <= 0) {
      setCart((current) =>
        current.filter((item) => item.variantId !== variantId),
      );
      return;
    }
    const available = getBalance(data.balances, loc, variantId);
    setCart((current) =>
      current.map((item) =>
        item.variantId === variantId
          ? { ...item, quantity: Math.min(quantity, available) }
          : item,
      ),
    );
  };
  useEffect(() => {
    if (shouldAutoFocusPosSearch)
      requestAnimationFrame(() => scannerRef.current?.focus());
  }, [shouldAutoFocusPosSearch]);
  // Izin kamera diminta dari handler klik; effect ini hanya memasang stream ke
  // video dan menjalankan pembacaan barcode agar Android tidak menolak izin.
  useEffect(() => {
    if (!cameraOpen || !scannerStreamRef.current) return;
    let cancelled = false;
    let detectorTimer: number | null = null;
    const start = async () => {
      try {
        const stream = scannerStreamRef.current;
        if (!stream || cancelled) return;
        if (scannerVideoRef.current) {
          scannerVideoRef.current.srcObject = stream;
          await scannerVideoRef.current.play();
        }
        const Detector = (window as any).BarcodeDetector;
        const preferredFormats = [
          "ean_13",
          "ean_8",
          "code_128",
          "code_39",
          "upc_a",
          "upc_e",
          "qr_code",
        ];
        const supportedFormats =
          typeof Detector.getSupportedFormats === "function"
            ? await Detector.getSupportedFormats()
            : preferredFormats;
        const formats = preferredFormats.filter((format) =>
          supportedFormats.includes(format),
        );
        const detector = formats.length
          ? new Detector({ formats })
          : new Detector();
        detectorTimer = window.setInterval(async () => {
          const video = scannerVideoRef.current;
          if (
            !video ||
            video.readyState < HTMLMediaElement.HAVE_CURRENT_DATA ||
            cancelled
          )
            return;
          try {
            const codes = await detector.detect(video);
            const rawValue = codes[0]?.rawValue;
            if (rawValue && applyScannedValue(rawValue)) stopCameraScanner();
          } catch {
            // Frame yang belum siap dibaca tidak boleh menghentikan kamera.
          }
        }, 280);
      } catch {
        setCameraError(
          "Pemindai kamera tidak dapat dijalankan. Perbarui Chrome atau gunakan scanner Bluetooth.",
        );
        stopCameraScanner();
      }
    };
    void start();
    return () => {
      cancelled = true;
      if (detectorTimer) window.clearInterval(detectorTimer);
      scannerStreamRef.current?.getTracks().forEach((track) => track.stop());
      scannerStreamRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cameraOpen]);
  useEffect(() => () => stopCameraScanner(), []);
  useEffect(
    () => () => {
      void scanAudioContextRef.current?.close();
    },
    [],
  );

  const totalQty = cart.reduce((acc, c) => acc + c.quantity, 0);
  const stockErrors = cart.filter(
    (item) => item.quantity > getBalance(data.balances, loc, item.variantId),
  );
  const priceForChannel = (variant: any) =>
    channel === "reseller"
      ? Number(variant?.resellerPrice || 0)
      : channel === "online"
        ? Number(variant?.onlinePrice ?? variant?.price ?? 0)
        : Number(variant?.price || 0);
  const totalAmount = cart.reduce((acc, c) => {
    const varDetail = variants.find((item: any) => item.id === c.variantId);
    const price = priceForChannel(varDetail);
    return acc + c.quantity * price;
  }, 0);
  const discountAmount =
    discountType === "percentage"
      ? Math.min(
          totalAmount,
          Math.round((totalAmount * Math.min(100, discountValue)) / 100),
        )
      : Math.min(totalAmount, Math.round(discountValue));
  const payableAmount = Math.max(0, totalAmount - discountAmount);
  useEffect(() => {
    setDiscountValue((current) =>
      discountType === "percentage"
        ? Math.min(current, 100)
        : Math.min(current, totalAmount),
    );
  }, [discountType, totalAmount]);

  return (
    <Modal
      title="Catat penjualan"
      desc="Catat penjualan untuk mengurangi stok dan mencatat riwayat transaksi."
      close={
        pendingSale
          ? () =>
              notify(
                "Selesaikan cetak atau batalkan transaksi terlebih dahulu.",
                "error",
              )
          : close
      }
      className="large pos-modal"
    >
      <form
        onSubmit={async (e) => {
          e.preventDefault();
          if (cart.length === 0 || saving) return;
          const shouldPrint = printReceipt;
          setSaving(true);
          try {
            const result = await save(
              loc,
              channel,
              cart,
              payment,
              shouldPrint,
              discountAmount,
              discountType,
              discountValue,
              buyerNote.trim() || undefined,
            );
            if (shouldPrint) {
              try {
                setPendingSale(result);
                await printPendingSale(result);
              } catch (printError) {
                const message =
                  printError instanceof Error
                    ? printError.message
                    : "periksa koneksi printer";
                setPrintError(message);
                notify(
                  `Struk gagal dicetak. Transaksi belum selesai: ${message}`,
                  "error",
                );
                setSaving(false);
              }
              return;
            }
            prepareNextSale();
          } catch (error) {
            notify(
              error instanceof Error
                ? error.message
                : "Penjualan tidak dapat disimpan.",
              "error",
            );
            setSaving(false);
          }
        }}
      >
        <button
          type="button"
          className="pos-settings-toggle"
          aria-expanded={transactionSettingsOpen}
          onClick={() => setTransactionSettingsOpen((current) => !current)}
        >
          <span>
            <Settings size={17} />
            <span>
              <b>Pengaturan Transaksi</b>
              <small>
                {activeLocations.find((location: any) => location.id === loc)
                  ?.name || "Lokasi"}{" "}
                ·{" "}
                {channel === "offline"
                  ? "Offline"
                  : channel === "online"
                    ? "Online"
                    : "Reseller"}{" "}
                · {printReceipt ? "Cetak resi" : "Tanpa resi"}
              </small>
            </span>
          </span>
          {transactionSettingsOpen ? (
            <ChevronUp size={18} />
          ) : (
            <ChevronDown size={18} />
          )}
        </button>
        {transactionSettingsOpen && (
          <section className="pos-transaction-settings">
            <label className="receipt-print-toggle">
              <input
                type="checkbox"
                checked={printReceipt}
                onChange={(event) => setPrintReceipt(event.target.checked)}
              />
              <span>
                <b>Cetak resi setelah disimpan</b>
                <small>
                  Default tidak mencetak. Aktifkan hanya jika pelanggan
                  membutuhkan resi.
                </small>
              </span>
            </label>
            {printReceipt && (
              <PrinterConnectionPanel
                settings={printerSettings}
                setSettings={setPrinterSettings}
                notify={notify}
              />
            )}
            <div className="form-grid">
              <Field label="Lokasi">
                <select
                  value={loc}
                  disabled={Boolean(fixedLocation)}
                  onChange={(e) => setLoc(e.target.value)}
                >
                  {activeLocations.map((l: any) => (
                    <option key={l.id} value={l.id}>
                      {l.name}
                    </option>
                  ))}
                </select>
              </Field>
              <Field label="Kanal">
                <select
                  value={channel}
                  onChange={(e) => setChannel(e.target.value as Channel)}
                >
                  <option value="offline">Offline</option>
                  <option value="online">Online</option>
                  <option value="reseller">Reseller</option>
                </select>
              </Field>
            </div>
          </section>
        )}

        {channel === "online" && (
          <div style={{ padding: "0 24px" }}>
            <div className="pos-category-tabs" style={{ padding: "8px 0 16px" }}>
              <button
                type="button"
                className={onlineInputMode === "satuan" ? "active" : ""}
                onClick={() => setOnlineInputMode("satuan")}
              >
                Satuan (Manual)
              </button>
              <button
                type="button"
                className={onlineInputMode === "bulk" ? "active" : ""}
                onClick={() => setOnlineInputMode("bulk")}
              >
                Bulk Process (Import Excel)
              </button>
            </div>
          </div>
        )}

        {channel === "online" && onlineInputMode === "bulk" ? (
          <BulkOnlineProcessor
            data={data}
            variants={variants}
            loc={loc}
            save={save}
            notify={notify}
            checkMarketplaceImport={checkMarketplaceImport}
          />
        ) : (
        <div className="pos-counter-workspace">
          <section className="pos-catalog-panel">
            <div
              className="pos-product-picker"
              style={{
                background: "var(--bg)",
                padding: "16px",
                borderRadius: "8px",
                marginBottom: "16px",
                border: "1px solid var(--border)",
              }}
            >
              <h4
                style={{
                  margin: "0 0 12px",
                  fontSize: 13,
                  color: "var(--muted)",
                }}
              >
                TAMBAH PRODUK
              </h4>
              <Field label="">
                <div className="pos-scan-row">
                  <input
                    ref={scannerRef}
                    value={skuSearch}
                    onChange={(e) => setSkuSearch(e.target.value)}
                    placeholder={
                      selectedPosProduct
                        ? "Cari varian atau SKU"
                        : "Cari produk"
                    }
                    autoComplete="off"
                    inputMode="search"
                    onPointerDown={primeScanAudio}
                    onKeyDown={(e) => {
                      if (e.key !== "Enter") return;
                      e.preventDefault();
                      if (!applyScannedValue(skuSearch))
                        setCameraError(
                          "Barcode atau SKU tidak ditemukan pada stok lokasi ini.",
                        );
                    }}
                  />
                  <button
                    type="button"
                    className="pos-camera-button"
                    onClick={() => {
                      primeScanAudio();
                      void openCameraScanner();
                    }}
                    aria-label="Pindai barcode dengan kamera"
                  >
                    <Camera size={18} />
                    <span>Scan</span>
                  </button>
                  <input
                    ref={barcodePhotoRef}
                    type="file"
                    accept="image/*"
                    capture="environment"
                    className="visually-hidden"
                    onChange={scanBarcodePhoto}
                  />
                </div>
                {cameraError && (
                  <div className="pos-scan-feedback" role="status">
                    <span>{cameraError}</span>
                    <button
                      type="button"
                      onClick={() => barcodePhotoRef.current?.click()}
                    >
                      Pilih foto barcode
                    </button>
                  </div>
                )}
                {cameraOpen && (
                  <div className="pos-camera-scanner">
                    <video
                      ref={scannerVideoRef}
                      muted
                      playsInline
                      aria-label="Pratinjau kamera pemindai barcode"
                    />
                    <div>
                      <span>Arahkan kamera ke barcode produk</span>
                      <button type="button" onClick={stopCameraScanner}>
                        <X size={16} /> Tutup kamera
                      </button>
                    </div>
                  </div>
                )}
                {selectedPosProduct && (
                  <div className="pos-variant-navigation">
                    <button
                      type="button"
                      onClick={() => {
                        setSelectedPosProduct(null);
                        setSkuSearch("");
                        resetPosVariantFilters();
                        releasePosSearchFocus();
                      }}
                    >
                      <ChevronLeft size={18} /> Kembali
                    </button>
                    <div>
                      <small>PRODUK TERPILIH</small>
                      <b>{selectedPosProduct}</b>
                    </div>
                    <div
                      className="pos-selected-variant-filters"
                      aria-label="Filter varian produk terpilih"
                    >
                      <select
                        aria-label="Filter berat atau kemasan"
                        value={posPackageFilter}
                        onChange={(event) =>
                          setPosPackageFilter(event.target.value)
                        }
                      >
                        <option value="all">Semua kemasan</option>
                        {posPackageOptions.map((value: any) => (
                          <option key={value} value={value}>
                            {value}
                          </option>
                        ))}
                      </select>
                      <select
                        aria-label="Filter varian rasa"
                        value={posFlavorFilter}
                        onChange={(event) =>
                          setPosFlavorFilter(event.target.value)
                        }
                      >
                        <option value="all">Semua rasa</option>
                        {posFlavorOptions.map((value: any) => (
                          <option key={value} value={value}>
                            {value}
                          </option>
                        ))}
                      </select>
                      <select
                        aria-label="Filter level"
                        value={posLevelFilter}
                        onChange={(event) =>
                          setPosLevelFilter(event.target.value)
                        }
                      >
                        <option value="all">Semua level</option>
                        {posLevelOptions.map((value: any) => (
                          <option key={value} value={value}>
                            {value}
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>
                )}
                {!selectedPosProduct && (
                  <div
                    className="pos-category-tabs"
                    aria-label="Kategori produk"
                  >
                    <button
                      type="button"
                      className={categoryFilter === "all" ? "active" : ""}
                      onClick={() => setCategoryFilter("all")}
                    >
                      Semua
                    </button>
                    {categories.map((category) => (
                      <button
                        type="button"
                        key={category}
                        className={categoryFilter === category ? "active" : ""}
                        onClick={() => setCategoryFilter(category)}
                      >
                        {category}
                      </button>
                    ))}
                  </div>
                )}
                <div
                  className={`pos-product-results ${selectedPosProduct ? "showing-variants" : "showing-products"}`}
                  style={{
                    maxHeight: 200,
                    overflowY: "auto",
                    border: "1px solid var(--line)",
                    borderRadius: 6,
                    padding: 8,
                    marginTop: 8,
                    background: "white",
                  }}
                >
                  {visibleProductGroups.length === 0 && (
                    <p className="pos-empty-products">
                      {selectedPosProduct
                        ? "Varian tidak ditemukan. Ubah pencarian atau filter yang dipilih."
                        : "Tidak ada varian tersedia untuk lokasi ini. Tambahkan stok terlebih dahulu."}
                    </p>
                  )}
                  {visibleProductGroups
                    .filter(
                      (product: any) =>
                        !selectedPosProduct ||
                        product.name === selectedPosProduct,
                    )
                    .map((product: any) => (
                      <section
                        className={`pos-product-group ${selectedPosProduct ? "variant-mode" : "product-mode"}`}
                        key={product.name}
                        role={!selectedPosProduct ? "button" : undefined}
                        tabIndex={!selectedPosProduct ? 0 : undefined}
                        aria-label={
                          !selectedPosProduct
                            ? `Lihat varian ${product.name}`
                            : undefined
                        }
                        onPointerDown={
                          !selectedPosProduct ? releasePosSearchFocus : undefined
                        }
                        onClick={
                          !selectedPosProduct
                            ? () => {
                                setSelectedPosProduct(product.name);
                                setSkuSearch("");
                                resetPosVariantFilters();
                                releasePosSearchFocus();
                              }
                            : undefined
                        }
                        onKeyDown={
                          !selectedPosProduct
                            ? (event) => {
                                if (event.key !== "Enter" && event.key !== " ")
                                  return;
                                event.preventDefault();
                                setSelectedPosProduct(product.name);
                                setSkuSearch("");
                                resetPosVariantFilters();
                                releasePosSearchFocus();
                              }
                            : undefined
                        }
                      >
                        <header>
                          <div className="pos-product-image">
                            <span>
                              {product.name.slice(0, 2).toUpperCase()}
                            </span>
                            {product.imageUrl && (
                              <img
                                src={product.imageUrl}
                                alt={product.name}
                                loading="lazy"
                                onError={(event) => {
                                  event.currentTarget.style.display = "none";
                                }}
                              />
                            )}
                          </div>
                          <div>
                            <b>{product.name}</b>
                            <small>
                              {product.variants.length} varian tersedia
                            </small>
                          </div>
                        </header>
                        {!selectedPosProduct ? null : (
                          <div className="pos-variant-list">
                            {product.variants.map((v: any) => {
                              const cartItem = cart.find(
                                (c) => c.variantId === v.id,
                              );
                              const checked = Boolean(cartItem);
                              const stockLimitReached =
                                (cartItem?.quantity || 0) >=
                                getBalance(data.balances, loc, v.id);
                              return (
                                <button
                                  type="button"
                                  className="pos-product-button"
                                  key={v.id}
                                  onClick={() => addToCart(v.id)}
                                  disabled={stockLimitReached}
                                >
                                  <span>
                                    <b>{v.name}</b>
                                    {(v.packageWeight ||
                                      v.flavor ||
                                      v.spiceLevel) && (
                                      <small className="pos-variant-attributes">
                                        {[
                                          v.packageWeight,
                                          v.flavor,
                                          v.spiceLevel,
                                        ]
                                          .filter(Boolean)
                                          .join(" · ")}
                                      </small>
                                    )}
                                    <small>
                                      Stok:{" "}
                                      {getBalance(data.balances, loc, v.id)}{" "}
                                      {v.unit} ·{" "}
                                      {money(
                                        priceForChannel(v),
                                      )}
                                    </small>
                                  </span>
                                  <strong>
                                    {stockLimitReached
                                      ? "Stok maksimal"
                                      : checked
                                        ? "+1 lagi"
                                        : "Tambah"}
                                  </strong>
                                </button>
                              );
                            })}
                          </div>
                        )}
                      </section>
                    ))}
                </div>
              </Field>
            </div>
          </section>
          <aside className="pos-order-panel">
            <div className="pos-order-heading">
              <div>
                <small>PESANAN AKTIF</small>
                <h3>Detail Pesanan</h3>
              </div>
              <span>{totalQty} item</span>
            </div>
            <div className="pos-order-scroll">
              {cart.length > 0 && (
                <>
                <div className="pos-cart-table" style={{ marginBottom: 16 }}>
                  <table
                    style={{
                      width: "100%",
                      fontSize: 13,
                      borderCollapse: "collapse",
                      textAlign: "left",
                    }}
                  >
                    <thead>
                      <tr style={{ borderBottom: "1px solid var(--border)" }}>
                        <th style={{ padding: "8px 0" }}>Produk</th>
                        <th style={{ padding: "8px 0" }}>Harga</th>
                        <th style={{ padding: "8px 0" }}>Qty</th>
                        <th style={{ padding: "8px 0", textAlign: "right" }}>
                          Subtotal
                        </th>
                        <th style={{ padding: "8px 0", width: 30 }}></th>
                      </tr>
                    </thead>
                    <tbody>
                      {cart.map((c, idx) => {
                        const varDetail = variants.find(
                          (item: any) => item.id === c.variantId,
                        );
                        if (!varDetail) return null;
                        const price = priceForChannel(varDetail);
                        return (
                          <tr
                            key={idx}
                            style={{ borderBottom: "1px solid var(--border)" }}
                          >
                            <td style={{ padding: "8px 0" }}>
                              {varDetail.productName} - {varDetail.name}
                            </td>
                            <td style={{ padding: "8px 0" }}>{money(price)}</td>
                            <td style={{ padding: "8px 0" }}>
                              <div className="pos-qty-control">
                                <button
                                  type="button"
                                  onClick={() =>
                                    updateQuantity(c.variantId, c.quantity - 1)
                                  }
                                  aria-label={`Kurangi ${varDetail.name}`}
                                >
                                  −
                                </button>
                                <b>{c.quantity}</b>
                                <span>{varDetail.unit}</span>
                                <button
                                  type="button"
                                  onClick={() =>
                                    updateQuantity(c.variantId, c.quantity + 1)
                                  }
                                  aria-label={`Tambah ${varDetail.name}`}
                                  disabled={
                                    c.quantity >=
                                    getBalance(data.balances, loc, c.variantId)
                                  }
                                >
                                  +
                                </button>
                              </div>
                            </td>
                            <td
                              style={{ padding: "8px 0", textAlign: "right" }}
                            >
                              {money(price * c.quantity)}
                            </td>
                            <td
                              style={{ padding: "8px 0", textAlign: "center" }}
                            >
                              <button
                                type="button"
                                className="pos-remove"
                                onClick={() => updateQuantity(c.variantId, 0)}
                                aria-label={`Hapus ${varDetail.name}`}
                              >
                                ×
                              </button>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
                <Field label="Diskon pembeli">
                  <div className="pos-discount-controls">
                    <select
                      aria-label="Jenis diskon pembeli"
                      value={discountType}
                      onChange={(event) => {
                        setDiscountType(
                          event.target.value as "nominal" | "percentage",
                        );
                        setDiscountValue(0);
                      }}
                    >
                      <option value="nominal">Nominal (Rp)</option>
                      <option value="percentage">Persentase (%)</option>
                    </select>
                    {discountType === "percentage" ? (
                      <div className="pos-discount-percentage-input">
                        <DecimalInput
                          label="Persentase diskon dari total belanja"
                          value={discountValue}
                          onValue={(value) =>
                            setDiscountValue(Math.min(value, 100))
                          }
                        />
                        <span>%</span>
                      </div>
                    ) : (
                      <RupiahInput
                        label="Diskon nominal dari total belanja"
                        value={discountValue}
                        onValue={(value) =>
                          setDiscountValue(Math.min(value, totalAmount))
                        }
                      />
                    )}
                  </div>
                  <small className="pos-note-hint">
                    {discountType === "percentage"
                      ? `${percentage(discountValue)} = ${money(discountAmount)}. `
                      : ""}
                    Diskon dipotong dari total transaksi dan tersimpan di laporan.
                  </small>
                </Field>
                <div
                  className="pos-cart-summary"
                  style={{
                    background: "var(--navy)",
                    color: "white",
                    padding: "12px 16px",
                    borderRadius: "8px",
                    marginTop: "12px",
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                  }}
                >
                  <div>
                    <div style={{ fontSize: 11, opacity: 0.8 }}>TOTAL TAGIHAN</div>
                    <div style={{ fontSize: 16, fontWeight: 700 }}>
                      {money(payableAmount)}
                    </div>
                    {discountAmount > 0 && (
                      <small style={{ opacity: 0.8 }}>
                        Subtotal {money(totalAmount)} · Diskon{" "}
                        {discountType === "percentage"
                          ? `${percentage(discountValue)} `
                          : ""}
                        −{money(discountAmount)}
                      </small>
                    )}
                  </div>
                  <div style={{ textAlign: "right" }}>
                    <div style={{ fontSize: 11, opacity: 0.8 }}>TOTAL QTY</div>
                    <div style={{ fontSize: 14, fontWeight: 600 }}>
                      {totalQty} item
                    </div>
                  </div>
                </div>
                </>
              )}

              <Field label="Catatan pesanan (opsional)">
                <input
                  className="pos-buyer-note"
                  maxLength={300}
                  value={buyerNote}
                  onChange={(event) => setBuyerNote(event.target.value)}
                  placeholder="Contoh: kurangi asin, bubuk cabai saja tanpa chili oil"
                />
                <small className="pos-note-hint">
                  Catatan akan tersimpan pada transaksi dan tercetak di struk.
                </small>
              </Field>
              <div className={isOffline ? "pos-payment" : "form-grid"}>
                <Field label="Metode Pembayaran">
                  {isOffline ? (
                    <div className="pos-payment-options">
                      {["QRIS", "Tunai", "Transfer"].map((method) => (
                        <button
                          key={method}
                          type="button"
                          className={payment === method ? "active" : ""}
                          onClick={() => setPayment(method)}
                        >
                          {method}
                        </button>
                      ))}
                    </div>
                  ) : (
                    <select
                      value={payment}
                      onChange={(e) => setPayment(e.target.value)}
                    >
                      <option>QRIS</option>
                      <option>Tunai</option>
                      <option>Transfer</option>
                    </select>
                  )}
                </Field>
                <div></div>
              </div>
              {printError && (
                <p className="form-error" role="alert">
                  Struk belum tercetak: {printError}
                </p>
              )}
              {stockErrors.length > 0 && (
                <p className="form-error" role="alert">
                  Jumlah penjualan melebihi stok tersedia. Kurangi jumlah item
                  sebelum menyimpan.
                </p>
              )}
            </div>
            <footer className="modal-actions sale-print-actions">
              {pendingSale ? (
                <>
                  <button
                    type="button"
                    className="danger-button"
                    onClick={() => void cancelPendingSale()}
                    disabled={saving}
                  >
                    Batalkan transaksi
                  </button>
                  <button
                    type="button"
                    className="secondary"
                    onClick={() => void printPendingSale()}
                    disabled={
                      saving ||
                      (printerSettings.mode !== "system" &&
                        !isPrinterConnected(printerSettings.mode))
                    }
                  >
                    <Printer size={17} />
                    Cetak ulang
                  </button>
                  <button
                    type="button"
                    className="primary"
                    onClick={() => void finishPendingSale()}
                    disabled={saving}
                  >
                    <Check size={17} />
                    Struk sudah tercetak
                  </button>
                </>
              ) : (
                <>
                  <button
                    type="button"
                    className="secondary"
                    onClick={close}
                    disabled={saving}
                  >
                    Batal
                  </button>
                  <button
                    type="submit"
                    className="primary"
                    disabled={
                      cart.length === 0 ||
                      stockErrors.length > 0 ||
                      discountAmount > totalAmount ||
                      (discountType === "percentage" && discountValue > 100) ||
                      saving ||
                      (printReceipt &&
                        printerSettings.mode !== "system" &&
                        !isPrinterConnected(printerSettings.mode))
                    }
                  >
                    {printReceipt ? <Printer size={17} /> : <Check size={17} />}
                    {saving
                      ? "Memproses..."
                      : printReceipt
                        ? "Simpan & Cetak"
                        : "Simpan Penjualan"}
                  </button>
                </>
              )}
            </footer>
          </aside>
        </div>
        )}
      </form>
    </Modal>
  );
}
function OpnameModal({ data, item, close, save, fixedLocation }: any) {
  const [isSaving, setIsSaving] = useState(false);
  const products = data.products
      .filter(
        (product: any) =>
          product.active &&
          product.variants.some((variant: any) => variant.active !== false),
      )
      .map((product: any) => ({
        ...product,
        variants: product.variants.filter(
          (variant: any) => variant.active !== false,
        ),
      })),
    variants = products.flatMap((product: any) =>
      product.variants.map((variant: any) => ({
        ...variant,
        unit: product.unit,
        productName: product.name,
      })),
    ),
    initialProductId = item
      ? products.find((product: any) =>
          product.variants.some(
            (variant: any) => variant.id === item.variantId,
          ),
        )?.id || ""
      : "",
    [loc, setLoc] = useState(
      item?.locationId ||
        fixedLocation ||
        data.locations[1]?.id ||
        data.locations[0]?.id ||
        "",
    ),
    [selectedProductId, setSelectedProductId] = useState(initialProductId),
    [productPickerOpen, setProductPickerOpen] = useState(false),
    [productSearch, setProductSearch] = useState(""),
    [selectedItems, setSelectedItems] = useState<
      Record<string, { actualQty: number | ""; reason: string }>
    >(
      item
        ? {
            [item.variantId]: {
              actualQty: item.actualQty || 0,
              reason: item.reason || "Koreksi saldo dari halaman stok",
            },
          }
        : {},
    );
  const productPickerRef = useDismissiblePopover(
    productPickerOpen,
    setProductPickerOpen,
  );
  const selectedProduct = products.find(
    (product: any) => product.id === selectedProductId,
  );
  const visibleVariants =
    selectedProduct?.variants.map((variant: any) => ({
      ...variant,
      unit: selectedProduct.unit,
      productName: selectedProduct.name,
    })) || [];
  const matchingProducts = products.filter((product: any) =>
    product.name.toLowerCase().includes(productSearch.toLowerCase()),
  );
  const invalidItems = Object.values(selectedItems).some(
    (selectedItem) =>
      selectedItem.actualQty === "" ||
      !Number.isInteger(Number(selectedItem.actualQty)) ||
      Number(selectedItem.actualQty) < 0 ||
      selectedItem.reason.trim().length < 3,
  );
  const selectProduct = (product: any) => {
    setSelectedProductId(product.id);
    setProductPickerOpen(false);
    setProductSearch("");
    blurFocusedTextInput();
  };

  return (
    <Modal
      title="Catat stock opname"
      desc="Selisih akan menjadi koreksi dengan jejak audit."
      close={close}
    >
      <form
        onSubmit={async (e) => {
          e.preventDefault();
          if (isSaving) return;
          if (Object.keys(selectedItems).length === 0 || invalidItems) {
            return;
          }
          setIsSaving(true);
          try {
            await save(
              loc,
              Object.entries(selectedItems).map(([vid, val]) => ({
                variantId: vid,
                actualQty: Number(val.actualQty),
                reason: val.reason,
              })),
            );
          } catch {
            // Callback halaman sudah menampilkan pesan error.
          } finally {
            setIsSaving(false);
          }
        }}
      >
        <Field label="Lokasi opname">
          <AppSelect
            value={loc}
            disabled={Boolean(fixedLocation)}
            onChange={(e: any) => setLoc(e.target.value)}
          >
            {data.locations
              .filter((l: any) => l.active || l.id === loc)
              .map((l: any) => (
                <option key={l.id} value={l.id}>
                  {l.type === "warehouse" ? "🏢 Gudang: " : "🏪 Outlet: "}
                  {l.name}
                </option>
              ))}
          </AppSelect>
        </Field>
        {!item && (
          <Field label="Scan barang fisik">
            <BarcodeScanControl
              label="Scan barang"
              onDetected={(value) => {
                const variant = findVariantByBarcode(variants, value);
                if (!variant) return false;
                const product = products.find((current: any) =>
                  current.variants.some(
                    (currentVariant: any) => currentVariant.id === variant.id,
                  ),
                );
                if (!product) return false;
                setSelectedProductId(product.id);
                setProductPickerOpen(false);
                setSelectedItems((current) => ({
                  ...current,
                  [variant.id]: current[variant.id] || {
                    actualQty: "",
                    reason: "Hasil hitung fisik akhir hari",
                  },
                }));
                return true;
              }}
            />
            <small className="scan-field-hint">
              Setelah scan, masukkan jumlah fisik aktual untuk menyelesaikan
              opname.
            </small>
          </Field>
        )}
        <Field label="Pilih produk">
          <div ref={productPickerRef} className="product-picker">
            <button
              type="button"
              className={`product-picker-trigger ${productPickerOpen ? "open" : ""}`}
              onClick={() => setProductPickerOpen((open) => !open)}
              aria-expanded={productPickerOpen}
            >
              <span>{selectedProduct?.name || "Pilih nama produk"}</span>
              <ChevronDown size={18} />
            </button>
            {productPickerOpen && (
              <div className="product-picker-panel">
                <label className="product-picker-search">
                  <Search size={17} />
                  <input
                    autoFocus={shouldAutoFocusTextInput()}
                    value={productSearch}
                    onChange={(e) => setProductSearch(e.target.value)}
                    placeholder="Cari nama produk"
                  />
                </label>
                <div className="product-picker-options">
                  {matchingProducts.length ? (
                    matchingProducts.map((product: any) => (
                      <button
                        type="button"
                        key={product.id}
                        className={
                          product.id === selectedProductId ? "selected" : ""
                        }
                        onTouchEnd={(event) =>
                          selectFromTouch(event, () => selectProduct(product))
                        }
                        onClick={() => selectProduct(product)}
                      >
                        <span>{product.name}</span>
                        <small>{product.variants.length} varian</small>
                        {product.id === selectedProductId && (
                          <Check size={16} />
                        )}
                      </button>
                    ))
                  ) : (
                    <p>Produk tidak ditemukan.</p>
                  )}
                </div>
              </div>
            )}
          </div>
        </Field>
        {selectedProduct && (
          <Field label={`Pilih varian ${selectedProduct.name}`}>
            <div className="variant-picker-list">
              {visibleVariants.map((v: any) => (
                <label key={v.id} className="variant-picker-option">
                  <input
                    type="checkbox"
                    checked={!!selectedItems[v.id]}
                    style={{ width: "auto", padding: 0, margin: 0 }}
                    onChange={(e) => {
                      if (e.target.checked) {
                        setSelectedItems({
                          ...selectedItems,
                          [v.id]: {
                            actualQty: "",
                            reason: "Hasil hitung fisik akhir hari",
                          },
                        });
                      } else {
                        const next = { ...selectedItems };
                        delete next[v.id];
                        setSelectedItems(next);
                      }
                    }}
                  />
                  <span>
                    <b>{v.name}</b>
                    <small className="variant-stock">
                      Stok sistem saat ini:{" "}
                      {qty(getBalance(data.balances, loc, v.id), v.unit)}
                    </small>
                  </span>
                </label>
              ))}
            </div>
          </Field>
        )}
        {!selectedProduct && (
          <p className="variant-picker-hint">
            Pilih nama produk untuk menampilkan varian yang akan dihitung.
          </p>
        )}
        {Object.keys(selectedItems).length > 0 && (
          <div style={{ marginTop: 16, marginBottom: 16 }}>
            <h4 style={{ margin: "0 0 12px", fontSize: 14 }}>
              Varian Terpilih:
            </h4>
            {Object.entries(selectedItems).map(([vid, selectedItem]) => {
              const v = variants.find((x: any) => x.id === vid);
              if (!v) return null;
              return (
                <div key={vid} className="opname-selected-item">
                  <div className="opname-item-head">
                    <div>
                      <b>
                        {v.productName} · {v.name}
                      </b>
                      <small>
                        Stok sistem:{" "}
                        {qty(getBalance(data.balances, loc, v.id), v.unit)}
                      </small>
                    </div>
                    {selectedItem.actualQty === "" ? (
                      <span className="status wait">Belum dihitung</span>
                    ) : (
                      <span
                        className={
                          Number(selectedItem.actualQty) -
                            getBalance(data.balances, loc, v.id) ===
                          0
                            ? "status ok"
                            : "status wait"
                        }
                      >
                        {Number(selectedItem.actualQty) -
                          getBalance(data.balances, loc, v.id) ===
                        0
                          ? "Sesuai"
                          : `Selisih ${Number(selectedItem.actualQty) - getBalance(data.balances, loc, v.id) > 0 ? "+" : ""}${qty(Number(selectedItem.actualQty) - getBalance(data.balances, loc, v.id), v.unit)}`}
                      </span>
                    )}
                  </div>
                  <div className="form-grid">
                    <Field label={`Stok fisik (${v.unit})`}>
                      <input
                        type="number"
                        min="0"
                        step="1"
                        required
                        placeholder="Masukkan hasil hitung"
                        value={selectedItem.actualQty}
                        onInput={(e) => {
                          const raw = e.currentTarget.value;
                          const actualQty =
                            raw === ""
                              ? ""
                              : Math.max(0, Math.trunc(Number(raw) || 0));
                          setSelectedItems((current) => ({
                            ...current,
                            [vid]: { ...current[vid], actualQty },
                          }));
                        }}
                        style={{ background: "white" }}
                      />
                    </Field>
                    <Field label="Alasan / catatan">
                      <textarea
                        required
                        value={selectedItem.reason}
                        onChange={(e) => {
                          const reason = e.currentTarget.value;
                          setSelectedItems((current) => ({
                            ...current,
                            [vid]: { ...current[vid], reason },
                          }));
                        }}
                        style={{ background: "white" }}
                      />
                    </Field>
                  </div>
                </div>
              );
            })}
          </div>
        )}
        <ModalActions
          close={close}
          disabled={
            isSaving || Object.keys(selectedItems).length === 0 || invalidItems
          }
        />
      </form>
    </Modal>
  );
}
function CancelModal({ close, save }: any) {
  const [isSaving, setIsSaving] = useState(false);
  const [reason, setReason] = useState("");
  return (
    <Modal
      title="Batalkan transaksi"
      desc="Stok akan dikoreksi otomatis. Transaksi asli dan alasan tetap ada dalam histori."
      close={close}
    >
      <form
        onSubmit={async (e) => {
          e.preventDefault();
          if (isSaving) return;
          setIsSaving(true);
          try {
            await save(reason);
          } finally {
            setIsSaving(false);
          }
        }}
      >
        <Field label="Alasan pembatalan / koreksi">
          <textarea
            required
            minLength={5}
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder="Contoh: Salah memilih produk atau jumlah"
          />
        </Field>
        <footer className="modal-actions">
          <button type="button" className="secondary" onClick={close}>
            Kembali
          </button>
          <button className="danger-button" type="submit" disabled={isSaving}>
            <RotateCcw />
            Batalkan transaksi
          </button>
        </footer>
      </form>
    </Modal>
  );
}
function SaleDetail({
  item,
  data,
  variants,
  locations,
  close,
  notify,
  finalizePrint,
}: any) {
  const [printerSettings, setPrinterSettings] = useState<PrinterSettings>(() =>
    loadPrinterSettings(),
  );
  const [printing, setPrinting] = useState(false);
  const [awaitingSystemConfirmation, setAwaitingSystemConfirmation] =
    useState(false);
  if (!item) return null;
  const grossTotal = Number(
    item.grossTotal ??
      (item.items.reduce(
        (sum: number, line: any) => sum + Number(line.subtotal || 0),
        0,
      ) || item.total),
  );
  const transactionDiscount = Number(item.discountAmount || 0);
  const hasCompleteHpp = item.items.every((line: any) =>
    Number.isFinite(Number(line.unitCost)),
  );
  const transactionHpp = hasCompleteHpp
    ? item.items.reduce(
        (sum: number, line: any) =>
          sum + Number(line.quantity || 0) * Number(line.unitCost || 0),
        0,
      )
    : 0;
  const printReceipt = async () => {
    setPrinting(true);
    try {
      if (printerSettings.mode === "system")
        systemPrintSale(item, data, printerSettings);
      else await directPrintSale(item, data, printerSettings);
      if (item.status === "pending_print") {
        setAwaitingSystemConfirmation(true);
        notify(
          "Data struk sudah dikirim. Konfirmasi hanya setelah kertas benar-benar keluar.",
        );
      } else notify("Cetak ulang struk berhasil dikirim.");
    } catch (error) {
      notify(
        error instanceof Error ? error.message : "Struk tidak dapat dicetak.",
        "error",
      );
    } finally {
      setPrinting(false);
    }
  };
  return (
    <Modal
      title={`Detail transaksi ${item.id}`}
      desc="Rincian lengkap transaksi penjualan."
      close={close}
    >
      <div className="detail-list">
        <p>
          <span>Waktu</span>
          <b>{jakartaDateTime(item.createdAt)}</b>
        </p>
        <p>
          <span>Lokasi</span>
          <b>{locations[item.locationId]?.name}</b>
        </p>
        <p>
          <span>Kanal / pembayaran</span>
          <b>
            {item.channel} &middot; {item.payment}
          </b>
        </p>
        {item.note && (
          <p className="sale-detail-note">
            <span>Catatan pesanan</span>
            <b>{item.note}</b>
          </p>
        )}
        {item.items.map((line: any) => (
          <p key={line.variantId}>
            <span>
              {variants[line.variantId]?.productName} &middot;{" "}
              {variants[line.variantId]?.name}
              <small>
                {qty(line.quantity, variants[line.variantId]?.unit)} ×{" "}
                {money(
                  line.price ??
                    (line.quantity
                      ? Number(line.subtotal || 0) / line.quantity
                      : 0),
                )}
                {Number(line.discount || 0) > 0
                  ? ` · Diskon ${money(line.discount)}`
                  : ""}
              </small>
            </span>
            <b>{money(Number(line.subtotal || 0) - Number(line.discount || 0))}</b>
          </p>
        ))}
        <p>
          <span>Subtotal sebelum diskon</span>
          <b>{money(grossTotal)}</b>
        </p>
        {transactionDiscount > 0 && (
          <p>
            <span>
              Diskon pembeli
              {item.discountType === "percentage"
                ? ` (${percentage(item.discountValue)})`
                : ""}
            </span>
            <b>−{money(transactionDiscount)}</b>
          </p>
        )}
        <p>
          <span>Total dibayar</span>
          <b>{money(item.total)}</b>
        </p>
        {hasCompleteHpp && (
          <>
            <p>
              <span>HPP snapshot ({item.channel})</span>
              <b>{money(transactionHpp)}</b>
            </p>
            <p>
              <span>Estimasi laba kotor</span>
              <b>{money(Number(item.total || 0) - transactionHpp)}</b>
            </p>
          </>
        )}
        <p>
          <span>Status</span>
          <b>
            {item.status === "voided"
              ? `Dibatalkan: ${item.cancelReason}`
              : item.status === "pending_print"
                ? "Menunggu cetak"
                : "Selesai"}
          </b>
        </p>
      </div>
      {item.status !== "voided" && (
        <PrinterConnectionPanel
          settings={printerSettings}
          setSettings={setPrinterSettings}
          notify={notify}
        />
      )}
      <footer className="modal-actions detail-modal-actions">
        <button type="button" className="secondary" onClick={close}>
          Tutup
        </button>
        {item.status !== "voided" && (
          <button
            type="button"
            className="primary"
            onClick={() => void printReceipt()}
            disabled={
              printing ||
              (printerSettings.mode !== "system" &&
                !isPrinterConnected(printerSettings.mode))
            }
          >
            <Printer size={17} />
            {printing
              ? "Mencetak..."
              : item.status === "pending_print"
                ? "Cetak & selesaikan"
                : "Cetak ulang struk"}
          </button>
        )}
        {item.status === "pending_print" && awaitingSystemConfirmation && (
          <button
            type="button"
            className="primary"
            onClick={async () => {
              setPrinting(true);
              try {
                await finalizePrint(item.id);
                notify("Struk sudah tercetak. Transaksi berstatus selesai.");
                close();
              } catch (error) {
                notify(
                  error instanceof Error
                    ? error.message
                    : "Transaksi tidak dapat diselesaikan.",
                  "error",
                );
                setPrinting(false);
              }
            }}
            disabled={printing}
          >
            <Check size={17} />
            Struk sudah tercetak
          </button>
        )}
      </footer>
    </Modal>
  );
}
function ReceiptDetail({ items, variants, locations, close }: any) {
  if (!items?.length) return null;
  const receipt = items[0];
  const documentCode = receiptDisplayCode(receipt);
  const totalQuantity = items.reduce(
    (sum: number, item: any) => sum + item.quantity,
    0,
  );
  const totalValue = items.reduce(
    (sum: number, item: any) => sum + item.quantity * item.unitCost,
    0,
  );
  const isCancelled = items.every((item: any) => item.status === "cancelled");
  return (
    <Modal
      title={`Detail stok masuk ${documentCode}`}
      desc="Rincian seluruh varian pada satu proses penerimaan stok."
      close={close}
    >
      <div className="detail-list">
        <p>
          <span>Tanggal</span>
          <b>{jakartaDateTime(receipt.createdAt)}</b>
        </p>
        <p>
          <span>Sumber</span>
          <b>
            {receipt.sourceType === "production"
              ? "Hasil produksi"
              : receipt.supplierName || "Supplier"}
          </b>
        </p>
        <p>
          <span>Lokasi penerima</span>
          <b>
            {locations[receipt.locationId]?.name || "Lokasi tidak diketahui"}
          </b>
        </p>
        <p>
          <span>Penginput</span>
          <b>{receipt.createdBy || "Penginput tidak tercatat"}</b>
        </p>
        <p>
          <span>Varian diterima</span>
          <b>
            {items.length} varian · {totalQuantity.toLocaleString("id-ID")} item
          </b>
        </p>
        <div className="detail-transfer-items">
          {items.map((line: any) => (
            <p key={line.id}>
              <span>
                {variants[line.variantId]?.productName} ·{" "}
                {variants[line.variantId]?.name}
                <small className="block">
                  {qty(line.quantity, variants[line.variantId]?.unit)} ×{" "}
                  {money(line.unitCost)}
                </small>
              </span>
              <b>{money(line.quantity * line.unitCost)}</b>
            </p>
          ))}
        </div>
        {receipt.note && (
          <p>
            <span>Catatan</span>
            <b>{receipt.note}</b>
          </p>
        )}
        <p>
          <span>Bukti penerimaan</span>
          <b>
            {receipt.proofUrl ? (
              <a
                className="proof-link"
                href={receipt.proofUrl}
                target="_blank"
                rel="noreferrer"
              >
                Lihat gambar bukti
              </a>
            ) : (
              "Tidak dilampirkan"
            )}
          </b>
        </p>
        <p>
          <span>Total nilai</span>
          <b>{money(totalValue)}</b>
        </p>
        <p>
          <span>Status</span>
          <b>
            {isCancelled
              ? `Dibatalkan: ${receipt.cancelReason || "-"}`
              : "Selesai"}
          </b>
        </p>
      </div>
      <footer className="modal-actions detail-modal-actions">
        <button type="button" className="secondary" onClick={close}>
          Tutup
        </button>
      </footer>
    </Modal>
  );
}
